{"file_path":"src/policies.js","content":"/**
 * Advances and queries the per-key state of a single policy. Token amounts
 * for buckets are tracked as a numerator over the policy's `per`, so partial
 * refill periods stay exact rather than being rounded.
 */

function advanceBucket(policy, key, tick) {
  let s = policy.state.get(key)
  if (!s) {
    s = { numerator: policy.capacity * policy.per, lastTick: tick }
    policy.state.set(key, s)
    return s
  }
  const delta = tick - s.lastTick
  const capacityNumerator = policy.capacity * policy.per
  const grown = s.numerator + policy.refill * delta
  s.numerator = grown > capacityNumerator ? capacityNumerator : grown
  s.lastTick = tick
  return s
}

function advanceWindow(policy, key, tick) {
  let s = policy.state.get(key)
  if (!s) {
    s = { ticks: [] }
    policy.state.set(key, s)
  }
  const threshold = tick - policy.span
  let cut = 0
  while (cut < s.ticks.length && s.ticks[cut] <= threshold) cut++
  if (cut > 0) s.ticks = s.ticks.slice(cut)
  return s
}

/** Advances `policy`'s state for `key` to `tick`. */
export function advance(policy, key, tick) {
  return policy.type === 'bucket' ? advanceBucket(policy, key, tick) : advanceWindow(policy, key, tick)
}

/** Reports whether `policy` currently allows a request for `key`. Call `advance` first. */
export function allows(policy, key) {
  const s = policy.state.get(key)
  if (policy.type === 'bucket') return s.numerator >= policy.per
  return BigInt(s.ticks.length) < policy.limit
}

/** Records a request for `key` against `policy`. Only call when `allows` returned true. */
export function record(policy, key, tick) {
  const s = policy.state.get(key)
  if (policy.type === 'bucket') {
    s.numerator -= policy.per
  } else {
    s.ticks.push(tick)
  }
}
"}

