{"file_path":"src/simulate.js","content":"import { advance, allows, record } from './policies.js'

/**
 * Finds the route whose prefix matches `key` and is longest among matches,
 * or `null` when no route applies.
 */
function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (!best || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * Replays `events` against `policies` and `routes` in order, returning one
 * verdict per event plus per-key and overall totals.
 */
export function simulate({ policies, routes, events }) {
  const verdicts = []
  const perKey = new Map()

  for (const ev of events) {
    const route = findRoute(routes, ev.key)
    const policyNames = route ? route.policies : []
    const policyObjs = policyNames.map((name) => policies.get(name))

    for (const policy of policyObjs) advance(policy, ev.key, ev.tick)

    let denyName = null
    for (let i = 0; i < policyObjs.length; i++) {
      if (!allows(policyObjs[i], ev.key)) {
        denyName = policyNames[i]
        break
      }
    }
    const allowed = denyName === null
    if (allowed) {
      for (const policy of policyObjs) record(policy, ev.key, ev.tick)
    }

    let stat = perKey.get(ev.key)
    if (!stat) {
      stat = { allowed: 0, denied: 0 }
      perKey.set(ev.key, stat)
    }
    if (allowed) stat.allowed++
    else stat.denied++

    verdicts.push({ tick: ev.tick, key: ev.key, allowed, denyName })
  }

  return { verdicts, perKey }
}
"}

