{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { ParseError, parseLimiterFile } from './parser.js'
import { simulate } from './simulate.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }

  const text = readStdin()

  let parsed
  try {
    parsed = parseLimiterFile(text)
  } catch (err) {
    if (err instanceof ParseError) fail(err.message)
    throw err
  }

  const { verdicts, perKey } = simulate(parsed)

  if (mode === 'replay') {
    let out = ''
    for (const v of verdicts) {
      out += v.allowed ? `${v.tick} ${v.key} allow\n` : `${v.tick} ${v.key} deny ${v.denyName}\n`
    }
    process.stdout.write(out)
  } else {
    let out = ''
    let totalAllowed = 0
    let totalDenied = 0
    const keys = [...perKey.keys()].sort()
    for (const key of keys) {
      const stat = perKey.get(key)
      out += `${key} allowed=${stat.allowed} denied=${stat.denied}\n`
      totalAllowed += stat.allowed
      totalDenied += stat.denied
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
    process.stdout.write(out)
  }

  process.exit(0)
}

main()
"}

